import React, { useState } from 'react';
import Popup from './Popup';

const FormComponent = ({ selectedDepartment }) => {
  const [formData, setFormData] = useState({});
  const [showPopup, setShowPopup] = useState(false);

  // Handle form input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value
    }));
  };

  // Handle submit button click
  const handleSubmit = (e) => {
    e.preventDefault();
    setShowPopup(true); // Show the popup with the form data
  };

  // Confirm the submission (you can add actual form submission logic here)
  const handleConfirm = () => {
    alert('Form Submitted!');
    setShowPopup(false);
    // Add actual form submission logic here (e.g., API call)
  };

  // Cancel the popup and reset
  const handleCancel = () => {
    setShowPopup(false);
  };

  // Render the form dynamically based on the department fields (assuming these are defined elsewhere)
  const departmentFields = [
    { label: 'Type of Area', name: 'typeOfArea' },
    { label: 'Khasra No', name: 'khasraNo' },
    { label: 'Demarcation', name: 'demarcation' },
    { label: 'Total Cost', name: 'totalCost' },
    { label: 'Remarks', name: 'remarks' }
  ];

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <div className="form-container">
          {departmentFields.map((field, index) => (
            <div key={index}>
              <label>{field.label}:</label>
              <input
                type="text"
                name={field.name}
                value={formData[field.name] || ''}
                onChange={handleChange}
              />
            </div>
          ))}
          <button type="submit">Submit</button>
        </div>
      </form>

      {showPopup && (
        <Popup
          formData={formData}
          onConfirm={handleConfirm}
          onCancel={handleCancel}
        />
      )}
    </div>
  );
};

export default FormComponent;
